#!/usr/bin/env bash
# Generated by aws-run-guide.html. Read-only discovery; output is not anonymized.
# EXAMPLE: replace YOUR-ORG, YOUR_PERMISSION_SET and ACCOUNT_ID_1,ACCOUNT_ID_2 with your own values
# before running it, or generate your own script from aws-run-guide.html.
set -euo pipefail

# Which repo to use, in order: REPO_DIR if set; the rubrik-sizing-scripts checkout this script sits in;
# the checkout your current folder is in; otherwise ./rubrik-sizing-scripts in the folder you run it from
# (cloned after asking).
TOOL_REL="CLOUD/python/aws"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]:-$0}")" && pwd)"
if [ -z "${REPO_DIR:-}" ]; then
  for dir in "$SCRIPT_DIR" "$PWD"; do
    TOP="$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null || true)"
    if [ -n "$TOP" ] && [ -d "$TOP/$TOOL_REL" ]; then REPO_DIR="$TOP"; break; fi
  done
  REPO_DIR="${REPO_DIR:-$PWD/rubrik-sizing-scripts}"
fi
if [ ! -d "$REPO_DIR/$TOOL_REL" ]; then
  if [ -n "$(ls -A "$REPO_DIR" 2>/dev/null)" ]; then
    echo "$REPO_DIR exists but has no $TOOL_REL (wrong branch or not rubrik-sizing-scripts?)."
    echo "Switch it to branch master, or set REPO_DIR to another checkout."
    exit 1
  fi
  echo "No rubrik-sizing-scripts checkout found."
  read -r -p "Clone rubrikinc/rubrik-sizing-scripts into $REPO_DIR now (sparse)? [y/N] " clone
  case "$clone" in [yY]*) ;; *) echo "Aborted. Set REPO_DIR to an existing checkout."; exit 1 ;; esac
  git clone --depth 1 --filter=blob:none --sparse --branch master \
    https://github.com/rubrikinc/rubrik-sizing-scripts.git "$REPO_DIR"
  git -C "$REPO_DIR" sparse-checkout set CLOUD
fi
echo "Using repo: $REPO_DIR"
echo "Code: $(git -C "$REPO_DIR" log -n1 --format='%h %ad' --date=short 2>/dev/null || echo unknown)"

# The script never updates an existing checkout, so say if it is behind (SKIP_UPDATE_CHECK=1 skips this).
if [ -z "${SKIP_UPDATE_CHECK:-}" ]; then
  if git -C "$REPO_DIR" fetch -q origin master 2>/dev/null; then
    if ! git -C "$REPO_DIR" merge-base --is-ancestor FETCH_HEAD HEAD 2>/dev/null; then
      echo "WARNING: this checkout does not have the latest master."
      echo "Update it with: git -C \"$REPO_DIR\" pull --ff-only"
      read -r -p "Run with the code you have anyway? [y/N] " old
      case "$old" in [yY]*) ;; *) echo "Aborted."; exit 1 ;; esac
    fi
  else
    echo "(could not check for a newer version; continuing)"
  fi
fi

# The output folder; a relative path is taken next to this script.
OUT_DIR="$SCRIPT_DIR"/'output'
cd "$REPO_DIR/$TOOL_REL"

python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 9) else 1)' || { echo "Python 3.9 or newer is required."; exit 1; }
python3 -m venv .venv
source .venv/bin/activate
pip install -q -r requirements.txt

echo "You are about to scan with this AWS identity, as the Python tool sees it:"
python - <<'PY'
import sys
import boto3
try:
    who = boto3.client("sts", region_name="us-east-1").get_caller_identity()
except Exception as exc:
    print("The Python tool cannot use your AWS credentials: " + type(exc).__name__ + ": " + (str(exc).splitlines() or [""])[0][:200])
    print('If you signed in with "aws login", run:  eval "$(aws configure export-credentials --format env)"')
    print('or install the extra it needs:  pip install "botocore[crt]"')
    sys.exit(1)
print("  Account: " + who["Account"])
print("  ARN:     " + who["Arn"])
PY
read -r -p "Continue? [y/N] " ans
case "$ans" in [yY]*) ;; *) echo "Aborted."; exit 1 ;; esac

python main.py --sso --sso-start-url 'https://YOUR-ORG.awsapps.com/start' --role-name 'YOUR_PERMISSION_SET' --accounts 'ACCOUNT_ID_1,ACCOUNT_ID_2' --no-cost --output "$OUT_DIR"

ZIP="$(ls -t "$OUT_DIR"/aws_sizing_results_*.zip 2>/dev/null | head -1 || true)"
if [ -n "$ZIP" ]; then echo "Results: $ZIP (contains account and resource names; keep it local)"; fi
